Rule.Source:
import java.util.List;
import sailpoint.api.Provisioner;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningProject;
import sailpoint.object.ProvisioningResult;

String APP_NAME = "LDAP ApacheDS";

if (identityName == null) {
    return "ERROR: no identityName";
}
Identity identity = context.getObjectByName(Identity.class, identityName);
if (identity == null) {
    return "ERROR: identity " + identityName + " not found";
}
Application app = context.getObjectByName(Application.class, APP_NAME);
if (app == null) {
    return "ERROR: application " + APP_NAME + " not found";
}

String status = (String) identity.getAttribute("status");
if (!"Active".equals(status)) {
    return "SKIPPED " + identityName + ": status is " + status;
}
if (identity.getLink(app) != null) {
    return "SKIPPED " + identityName + ": already has an LDAP account";
}

// Ask for a new account; the Create Account policy fills in the attributes
ProvisioningPlan plan = new ProvisioningPlan();
plan.setIdentity(identity);
AccountRequest req = new AccountRequest();
req.setApplication(APP_NAME);
req.setOperation(AccountRequest.Operation.Create);
plan.add(req);

Provisioner provisioner = new Provisioner(context);
ProvisioningProject project = provisioner.compile(plan);
if (project.hasQuestions()) {
    return "ERROR " + identityName + ": Create Account policy left required fields empty";
}
provisioner.execute(project);

// Collect any errors reported by the connector
StringBuilder errors = new StringBuilder();
List plans = project.getPlans();
if (plans != null) {
    for (Object o : plans) {
        ProvisioningPlan p = (ProvisioningPlan) o;
        ProvisioningResult pr = p.getResult();
        if (pr != null && pr.isFailed()) errors.append(pr.getErrors());
        if (p.getAccountRequests() != null) {
            for (Object ar : p.getAccountRequests()) {
                ProvisioningResult r = ((AccountRequest) ar).getResult();
                if (r != null && r.isFailed()) errors.append(r.getErrors());
            }
        }
    }
}
if (errors.length() > 0) {
    log.error("LDAP provisioning failed for " + identityName + ": " + errors);
    return "FAILED " + identityName + ": " + errors;
}

context.decache();
identity = context.getObjectByName(Identity.class, identityName);
Link link = identity.getLink(app);
return "CREATED " + identityName + ": " + (link == null ? "(account requested)" : link.getNativeIdentity());
